/*
 Problem: 901. Online Stock Span
 Language: cpp
 Runtime: 32 ms (60.97%)
 Memory: 97.1 MB (60.46%)
 Tags: Stack, Design, Monotonic Stack, Data Stream
*/
class StockSpanner {
    stack<pair<int, int>> st;

public:
    int next(int price) {
        int span = 1;

        while (!st.empty() && st.top().first <= price) {
            span += st.top().second;
            st.pop();
        }

        st.push({price, span});
        return span;
    }
};

